/// The continuation prompt for an over-window resume, naming what the
/// compaction hid — record kinds + turn spans — and how to recover it
/// via `compact_expand` (issue #438 AC4). Nothing hidden (classic
/// compaction) keeps the fixed notice. The notice CLASS follows the
/// stop that armed the funnel ([_contextStopIsProbableOverflow]): the
/// guard's "request was NOT sent" story would be false for a
/// probable-overflow refusal, which the provider DID see.
Future<String> _overWindowContinuationPrompt() async {
  final base = _contextStopIsProbableOverflow
      ? _probableOverflowContinuationNotice
      : _overWindowContinuationNotice;
  _contextStopIsProbableOverflow = false;
  final session = _session;
  final recoverables = session == null
      ? ''
      : hiddenRecoverablesSummary(await session.getEntries());
  if (recoverables.isEmpty) return base;
  return base.replaceFirst(
    '</system-notice>',
    '$recoverables\n</system-notice>',
  );
}

