/// The gh-2470 probable-overflow verdict: non-null when the chain's
/// pre-commit failures are the DETERMINISTIC per-history class on a large
/// request — the identical error text on every attempt, the wording
/// carrying nothing a retry can heal (no transport wording, no rate
/// limit), and no definite class owning the failure already (definite
/// overflow patterns and budget exhaustion never exhaust this ladder —
/// they stand on attempt 1 — but the gate re-checks defensively), and the
/// request is LARGE for the model's window. Null keeps the generic
/// exhaustion story: a small request, a non-deterministic chain, or a
/// transient wording is honestly a "try again later" case.
ProbableOverflowTokens? _probableOverflowVerdict(
  _DriveState state,
  Model model,
) {
  if (state.failureTexts.length < 2) return null;
  final first = state.failureTexts.first;
  if (first.isEmpty) return null;
  if (state.failureTexts.any((text) => text != first)) return null;
  final failure = state.lastFailure;
  if (failure == null) return null;
  if (matchesTransientNetworkWording(first)) return null;
  if (matchesRateLimitWording(first)) return null;
  if (isBudgetExhaustion(failure)) return null;
  if (isContextOverflow(failure)) return null;
  final requestTokens = estimateProbableOverflowRequestTokens(state.context);
  if (!isProbableOverflowLargeRequest(
    requestTokens: requestTokens,
    contextWindow: model.contextWindow,
  )) {
    return null;
  }
  return ProbableOverflowTokens(
    requestTokens: requestTokens,
    contextWindow: model.contextWindow,
  );
}

